package akogen.fabric.v6;
import java.util.*;
/** Small Molang expression evaluator for the bundled, local animation assets. Angles are degrees. */
public final class Expr{
 static Map<String,Node> cache=new HashMap<String,Node>();public interface Node{double eval(Context c);}public static class Context{public double time,speed,forward,right,ownerDistance,limbPos,limbSpeed;public boolean running,crouching,headRig,armRig;public double headRotX,headRotY,headRotZ,headX,headY=22.5,headZ,armRotX,armRotY,armRotZ,armX=4.6875,armY=20.625,armZ;public double value(String n){if(n.equals("query.life_time")||n.equals("q.life_time")||n.equals("query.anim_time")||n.equals("q.anim_time"))return time;if(n.endsWith("is_running"))return running?1:0;if(n.endsWith("ground_speed"))return Math.abs(speed);if(n.endsWith("owner_distance"))return ownerDistance;if(n.endsWith("is_in_water"))return 0;if(n.endsWith("local_z_velocity_smoothed"))return forward;if(n.endsWith("local_y_velocity_smoothed"))return 0;return 0;}}
 public static double eval(String s,Context c){try{Node n=cache.get(s);if(n==null){n=new Parser(s).parse(0);cache.put(s,n);}double v=n.eval(c);return Double.isFinite(v)?v:0;}catch(Exception e){return 0;}}
 static class Parser{String s,t;int p;Parser(String s){this.s=s;next();}void next(){while(p<s.length()&&Character.isWhitespace(s.charAt(p)))p++;if(p==s.length()){t="";return;}int b=p;char c=s.charAt(p++);if(Character.isDigit(c)||c=='.'){while(p<s.length()&&(Character.isDigit(s.charAt(p))||s.charAt(p)=='.'))p++;}else if(Character.isLetter(c)||c=='_'){while(p<s.length()&&(Character.isLetterOrDigit(s.charAt(p))||"._".indexOf(s.charAt(p))>=0))p++;}else if(p<s.length()&&Arrays.asList("<=",">=","==","!=","&&","||").contains(s.substring(b,p+1)))p++;t=s.substring(b,p);}int prec(String o){if(o.equals("||"))return 1;if(o.equals("&&"))return 2;if(Arrays.asList("==","!=","<",">","<=",">=").contains(o))return 3;if(o.equals("+")||o.equals("-"))return 4;if(o.equals("*")||o.equals("/")||o.equals("%"))return 5;return -1;}
 Node parse(int min){Node left;final String token=t;next();if(token.equals("-")||token.equals("!")){final Node n=parse(6);left=c->token.equals("-")?-n.eval(c):(n.eval(c)==0?1:0);}else if(token.equals("(")){left=parse(0);if(t.equals(")"))next();}else if(!token.isEmpty()&&(Character.isDigit(token.charAt(0))||token.charAt(0)=='.')){final double v=Double.parseDouble(token);left=c->v;}else if(t.equals("(")){next();final List<Node> ns=new ArrayList<Node>();while(!t.equals(")")&&!t.isEmpty()){ns.add(parse(0));if(t.equals(","))next();else break;}if(t.equals(")"))next();left=c->{double a=ns.size()>0?ns.get(0).eval(c):0,b=ns.size()>1?ns.get(1).eval(c):0,d=ns.size()>2?ns.get(2).eval(c):0;String f=token.replace("math.","");switch(f){case"sin":return Math.sin(Math.toRadians(a));case"cos":return Math.cos(Math.toRadians(a));case"abs":return Math.abs(a);case"floor":return Math.floor(a);case"ceil":return Math.ceil(a);case"sqrt":return Math.sqrt(Math.max(0,a));case"pow":return Math.pow(a,b);case"max":return Math.max(a,b);case"min":return Math.min(a,b);case"clamp":return Math.max(b,Math.min(d,a));case"mod":return a%b;case"lerp":return a+(b-a)*d;default:return 0;}};}else left=c->c.value(token);
 while(prec(t)>=min){final String o=t;int pr=prec(o);next();final Node a=left,b=parse(pr+1);left=c->{double x=a.eval(c),y=b.eval(c);switch(o){case"+":return x+y;case"-":return x-y;case"*":return x*y;case"/":return y==0?0:x/y;case"%":return y==0?0:x%y;case"<":return x<y?1:0;case">":return x>y?1:0;case"<=":return x<=y?1:0;case">=":return x>=y?1:0;case"==":return x==y?1:0;case"!=":return x!=y?1:0;case"&&":return x!=0&&y!=0?1:0;case"||":return x!=0||y!=0?1:0;default:return 0;}};}
 if(min==0&&t.equals("?")){next();final Node cond=left,a=parse(0);if(t.equals(":"))next();final Node b=parse(0);left=c->cond.eval(c)!=0?a.eval(c):b.eval(c);}return left;}}
}
